import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const outPath = join(root, 'src', 'config', 'vercelBuildMeta.js');

function esc(value) {
  return String(value ?? '')
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'");
}

const gitRef = esc(process.env.VERCEL_GIT_COMMIT_REF ?? '');
const vercelEnv = esc(process.env.VERCEL_ENV ?? '');

const contents = `/**
 * AUTO-GENERATED by scripts/write-vercel-build-meta.mjs — do not edit by hand.
 * Regenerated on each Vercel build; local checkout uses committed defaults until \`npm run build\`.
 */
export const VERCEL_GIT_COMMIT_REF = '${gitRef}';
export const VERCEL_ENV = '${vercelEnv}';
`;

writeFileSync(outPath, contents, 'utf8');
console.log('[build-meta]', { VERCEL_GIT_COMMIT_REF: process.env.VERCEL_GIT_COMMIT_REF ?? '', VERCEL_ENV: process.env.VERCEL_ENV ?? '' });